mapper.insert:

    SELECT
        'MYLC'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(MY_LICENSE), LENGTH('MYLC' ) + 1)), 0) + 1, 6, '0')
    FROM MY_LICENSE

INSERT INTO MY_LICENSE (
	MY_LICENSE
	, RESUME_NO
	, LICENSE_CODE
	, LICENSE_PASS_DATE
) VALUES (
	#{myLicense}
	, #{resumeNo}
	, #{licenseCode}
	, REPLACE(#{licensePassDate}, '-', '')
)

mapper.update:
UPDATE MY_LICENSE 
   SET RESUME_NO = #{resumeNo}
       , LICENSE_CODE = #{licenseCode}
       , LICENSE_PASS_DATE = REPLACE(#{licensePassDate}, '-', '') 
 WHERE MY_LICENSE = #{myLicense}
